pub fn is_palindrome(s: &str) -> bool {
    let mut left: usize = 0;
    let mut right: usize = s.chars().count() as usize - 1;
    while left < right {
        if !is_alphanumeric(s.chars().nth(left).unwrap()) {
            left += 1;
        }
        if !is_alphanumeric(s.chars().nth(right).unwrap()) {
            right -= 1;
        } else {
            if s.chars().nth(left).unwrap().to_lowercase().next().unwrap() != s.chars().nth(right).unwrap().to_lowercase().next().unwrap() {
                return false;
            }
            left += 1;
            right -= 1;
        }
    }
    true
}

