pub fn rle(input: &str) -> String {
    let mut out = String::new();
    let mut count = 0;
    for (i, c) in input.chars().enumerate() {
        if i == 0 || c == input.chars().nth(i - 1).unwrap() {
            count += 1;
        } else {
            out.push_str(&format!("{}", count));
            out.push(c);
            count = 1;
        }
    }
    out.push_str(&format!("{}", count));
    out
}

