    if a == 0 || b == 0 {
        return 0;
    }
    let mut largest = a.max(b);
    while largest != 1 {
        if largest % a == 0 && largest % b == 0 {
            largest /= a;
            largest /= b;
        } else {
            largest -= 1;
        }
    }
    largest
}

