pub fn factorial(n: u32) -> Option<u64> {
    if n == 0 || n == 1 {
        return Some(1);
    }
    let mut total = 1u64;
    let mut left = n;
    while left > 0 {
        let remainder = left % 2;
        if remainder != 0 {
            total *= left as u64;
        }
        left /= 2;
    }
    Some(total)
}

